customMethods.script:
system.perspective.sendMessage('showInfoToast', 'Deleting serial number template.....')
retVal, msg = system.kanoa.serial.deleteSerialNumber(serialId, self.view.custom.security.userId)

if msg is None: system.perspective.sendMessage('showSuccessfulToast', 'Serial Number template deleted')
else: system.perspective.sendMessage('showFailerToast', "Couldn't delete this Serial Number template. \n%s"%msg)

self.view.refreshBinding("custom.serialNumbers.data")

return

viewParams = {"serialId": serialId, 'userId': self.view.custom.security.userId}
system.perspective.openPopup('serialEditorId', 'kanoa/mes/config/lots/serialEditor', {'value': viewParams}, title= 'Edit Serialization', showCloseIcon=True, draggable=True, resizable=True)

return

